$(document).ready(function() {
    $(".zero-configuration").DataTable();
    var o = $(".row-grouping").DataTable({
        columnDefs: [{
            visible: !1,
            targets: 2
        }],
        order: [
            [2, "asc"]
        ],
        displayLength: 10,
        drawCallback: function(a) {
            var o = this.api(),
                t = o.rows({
                    page: "current"
                }).nodes(),
                r = null;
            o.column(2, {
                page: "current"
            }).data().each(function(a, o) {
                r !== a && ($(t).eq(o).before('<tr class="group"><td colspan="5">' + a + "</td></tr>"), r = a)
            })
        }
    });
    $(".row-grouping tbody").on("click", "tr.group", function() {
        var a = o.order()[0];
        2 === a[0] && "asc" === a[1] ? o.order([2, "desc"]).draw() : o.order([2, "asc"]).draw()
    }),
  
     $(".complex-headers").DataTable(
        {


            language: {
                paginate: {
                  // remove previous & next text from pagination
                  previous: '&nbsp;',
                  next: '&nbsp;'
                }
              },
            
            columnDefs: [{
              
            }, {
                targets: 0,
                render: function(e, t, a, s) {
                    return "display" === t && (e = '<div class="custom-control custom-checkbox"> <input class="custom-control-input dt-checkboxes" type="checkbox" value=""  id="checkbox2"><label class="custom-control-label"  for="checkbox2" ></label></div>'), e
                },
                checkboxes: {
                    selectRow: !0,
                    selectAllRender: '<div class="custom-control custom-checkbox"> <input class="custom-control-input" type="checkbox" value="" id="checkboxSelectAll" /> <label class="custom-control-label" for="checkboxSelectAll"></label></div>'
                }
            }],
             select: { style: "multi", selector: "td:first-child", items: "row" },
           
        }
    );
    $('input.dt-input').on('keyup', function () {
     
        filterColumn($(this).attr('data-column'), $(this).val());
        alert($(this).val())
      });
    var a = $(".add-rows").DataTable(),
        t = 2;
    $("#addRow").on("click", function() {
        a.row.add([t + ".1", t + ".2", t + ".3", t + ".4", t + ".5"]).draw(!1), t++
    }), $(".dataex-html5-selectors").DataTable({
        dom: "Bfrtip",
        buttons: [{
            extend: "copyHtml5",
            exportOptions: {
                columns: [0, ":visible"]
            }
        }, {
            extend: "pdfHtml5",
            exportOptions: {
                columns: ":visible"
            }
        }, {
            text: "JSON",
            action: function(a, o, t, r) {
                var e = o.buttons.exportData();
                $.fn.dataTable.fileSave(new Blob([JSON.stringify(e)]), "Export.json")
            }
        }, {
            extend: "print",
            exportOptions: {
                columns: ":visible"
            }
        }]
    }), $(".scroll-horizontal-vertical").DataTable({
        scrollY: 200,
        scrollX: !0
    })

   
});



